def find_path(grid, start, goal):
    # Define movements (up, down, left, right)
    movements = [(0, -1), (0, 1), (-1, 0), (1, 0)]

    # Find the coordinates of the start and goal states
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == start:
                start_coords = (i, j)
            elif grid[i][j] == goal:
                goal_coords = (i, j)

    # Perform BFS to find the shortest path
    queue = [(start_coords, [start])]
    visited = set()

    while queue:
        (x, y), path = queue.pop(0)

        if (x, y) == goal_coords:
            return path

        for dx, dy in movements:
            nx, ny = x + dx, y + dy

            # Check if the new position is within the grid boundaries
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
                # Check if the new position is not an obstacle and has not been visited before
                if grid[nx][ny] != "X" and (nx, ny) not in visited:
                    queue.append(((nx, ny), path + [grid[nx][ny]]))
                    visited.add((nx, ny))

    # If no path is found, return an empty list
    return []

def main():
    grid = [[0,2,4,8,10],[1,"X",7,"X",12],[3,6,"X",18,14],[5,"X",15,"X",17],[9,11,13,16,19]]
    start = 0
    goal = 19

    path = find_path(grid, start, goal)

    # Format the output as a list of lists, where each sublist contains a single integer representing a state in the path
    formatted_path = [[state] for state in path]

    print(formatted_path)

if __name__ == "__main__":
    main()
